select lot_id, lot_no, item_type, item_id, product_id, warehouse_id, source_lot_id, receipt_disposition, supplier_batch_no, production_date, expiry_date, qc_status, lot_status from inv_inventory_lot where lot_id in
#{lotId}
order by lot_id for update

select location_id, warehouse_id, location_code, location_name, location_type, sort_order, status, is_virtual from inv_warehouse_location where (location_id in
#{locationId}
or (warehouse_id = #{targetWarehouseId} and status = '0' and is_virtual = '0' and location_type in ('storage', 'quarantine'))) order by location_id for update

select lot_id, lot_no, item_type, item_id, product_id,
       warehouse_id, source_lot_id, receipt_disposition,
       supplier_batch_no, production_date, expiry_date,
       qc_status, lot_status
from inv_inventory_lot
where

    (warehouse_id = #{item.warehouseId}
     and item_type = #{item.itemType}
     and item_id = #{item.itemId}
     and source_lot_id = #{item.sourceLotId}
     and receipt_disposition = #{item.disposition})

order by lot_id
for update

mapper.update:
update inv_transfer_shipment_detail
set received_quantity = received_quantity
        + #{detail.fulfillmentDelta}
where shipment_detail_id = #{detail.detailId}
  and shipment_id = #{shipmentId}
  and transfer_id = #{transferId}
  and transfer_detail_id = #{transferDetailId}
  and received_quantity = #{detail.expectedReceivedQuantity}
  and #{detail.fulfillmentDelta} > 0
  and received_quantity + #{detail.fulfillmentDelta}
      = #{detail.receivedQuantityAfter}
  and received_quantity + #{detail.fulfillmentDelta}
      <= shipped_quantity

update inv_transfer_detail
set received_quantity = received_quantity
        + #{detail.fulfillmentDelta}
where detail_id = #{detail.detailId}
  and transfer_id = #{transferId}
  and received_quantity = #{detail.expectedReceivedQuantity}
  and #{detail.fulfillmentDelta} > 0
  and received_quantity + #{detail.fulfillmentDelta}
      = #{detail.receivedQuantityAfter}
  and received_quantity + #{detail.fulfillmentDelta}
      <= delivered_quantity
  and delivered_quantity <= quantity

update inv_transfer_shipment
set status = #{statusAfter},
    received_by = #{receivedBy},
    received_time = #{arrivedTime}
where shipment_id = #{shipmentId}
  and transfer_id = #{transferId}
  and inventory_write_version = 'V2_DETAIL'
  and status = #{expectedStatus}
  and #{expectedStatus} in ('pending_receive', 'partial_received')
  and #{statusAfter} in
      ('partial_received', 'received', 'discrepancy')
